    [10588]={name="Goblin Rocket Helmet",quality=2,ilvl=47,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering",reqSkills={{"Engineering",235}},proc="Use: Charge an enemy, knocking it silly for 30 seconds. Also knocks you down, stunning you for a short period of time. Any damage caused will revive the target.  Chance to fizzle w"},
    [10629]={name="Mistwalker Boots",quality=3,ilvl=50,reqLevel=45,sourceType="world_drop",instructions="World drop around level 45-50."},
