    [12038]={name="Lagrave's Seal",quality=2,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'The Last Element'.",zone="Blackrock Depths",questName="The Last Element",lore="There is work to be had for those venturing into the depths. The Dark Irons have mastered creation of extremely powerful golems."},
