    [13315]={name="Testament of Hope",quality=2,ilvl=61,reqLevel=55,sourceType="quest_reward",instructions="Reward from the quest 'The Restless Souls'.",zone="Stratholme",questName="The Restless Souls",lore="I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done.",proc="Use: Restores 554 to 678 health. Can only be used at 15% health. (6 Min Cooldown)"},
